from fastapi import APIRouter
from fastapi.responses import Response

router = APIRouter()


@router.get("/ui/agent-panel.js", include_in_schema=False)
def agent_panel_script():
    return Response(SCRIPT, media_type="application/javascript")


SCRIPT = r"""
(()=>{
if(!['/dashboard','/dashboard/','/atlas-ultimate','/atlas-ultimate/','/'].includes(location.pathname))return;
const root=document.querySelector('.shell')||document.querySelector('main');
if(!root||document.getElementById('atlas-agent-panel'))return;
const style=document.createElement('style');
style.textContent=`
.agent-panel,.atlas-chart-panel,.atlas-chat-panel{margin-top:12px}.agent-head,.chart-head,.chat-head{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap}.agent-controls,.chart-controls,.chat-actions{display:flex;gap:8px;flex-wrap:wrap}.agent-controls select,.agent-controls button,.chart-controls select,.chart-controls button,.chat-actions button,.atlas-chat-input{border:1px solid var(--line);border-radius:10px;padding:9px 11px;background:#fffaf2;color:#191919;font:inherit}.agent-controls button,.chart-controls button,.chat-actions button{background:var(--orange);color:#15100a;font-weight:900;cursor:pointer}.agent-controls button:disabled,.chart-controls button:disabled,.chat-actions button:disabled{opacity:.45;cursor:wait}.agent-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:13px}.agent-metric{border:1px solid var(--line);border-radius:12px;padding:11px;background:#fffaf2}.agent-value{font-size:18px;font-weight:900;margin-top:5px}.agent-skills{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}.agent-reasons{margin:12px 0 0;padding-left:18px;color:var(--muted)}.agent-reasons li{margin:5px 0}.agent-foot,.chart-meta,.chat-foot{margin-top:12px;font-size:11px;color:var(--muted)}.atlas-chart-wrap{margin-top:14px;border:1px solid #ff7a1a44;border-radius:16px;padding:10px;background:linear-gradient(180deg,#fffaf2,#f6efe5);overflow:hidden}.atlas-chart{width:100%;height:320px;display:block}.chart-grid{stroke:#c9bca9;stroke-width:1;opacity:.35}.chart-price{fill:none;stroke:#ff7a1a;stroke-width:3;vector-effect:non-scaling-stroke}.chart-ema{fill:none;stroke:#202020;stroke-width:2;stroke-dasharray:7 5;vector-effect:non-scaling-stroke}.chart-rsi{fill:none;stroke:#775b41;stroke-width:2;vector-effect:non-scaling-stroke}.chart-marker{fill:#ff7a1a;stroke:#fff;stroke-width:2}.chat-log{display:flex;flex-direction:column;gap:9px;max-height:280px;overflow:auto;margin-top:14px;padding:4px}.chat-bubble{max-width:86%;padding:10px 12px;border-radius:14px;white-space:pre-wrap;line-height:1.45}.chat-bubble.user{align-self:flex-end;background:#ff7a1a;color:#17110b}.chat-bubble.ai{align-self:flex-start;background:#fffaf2;border:1px solid var(--line);color:#191919}.chat-compose{display:grid;grid-template-columns:1fr auto;gap:8px;margin-top:12px}.atlas-chat-input{width:100%;min-height:44px}.chart-signal{display:inline-flex;align-items:center;gap:6px;padding:6px 9px;border-radius:999px;border:1px solid #ff7a1a55;background:#fff3e5;font-size:11px;font-weight:800}@media(max-width:720px){.agent-grid{grid-template-columns:1fr 1fr}.atlas-chart{height:250px}.chat-compose{grid-template-columns:1fr}.chat-actions button{width:100%}}
`;document.head.append(style);
const panel=document.createElement('section');panel.id='atlas-agent-panel';panel.className='card agent-panel';
panel.innerHTML=`<div class="agent-head"><div><div class="label">ATLAS Agent · Market Analysis</div><div class="mini">Signal + risk analysis for the selected market. No order is sent from this panel.</div></div><div class="agent-controls"><select id="agentSymbol"><option>XAUUSD</option><option>GAS</option><option>XAGUSD</option><option>EURUSD</option><option>XRPUSDT</option><option>SOLUSDT</option></select><select id="agentInterval"><option value="multi" selected>All: 5m + 15m + 30m + 1h</option><option>5m</option><option>15m</option><option>30m</option><option>1h</option></select><button id="agentRun">Analyze</button></div></div><div class="agent-grid"><div class="agent-metric"><div class="label">Decision</div><div class="agent-value" id="agentDecision">—</div></div><div class="agent-metric"><div class="label">Confidence</div><div class="agent-value" id="agentConfidence">—</div></div><div class="agent-metric"><div class="label">Trend</div><div class="agent-value" id="agentTrend">—</div></div><div class="agent-metric"><div class="label">Risk</div><div class="agent-value" id="agentRisk">—</div></div></div><div class="agent-grid" id="agentFrames" aria-live="polite"></div><div class="agent-skills" id="agentSkills"></div><ul class="agent-reasons" id="agentReasons"><li>Select a market and run ATLAS Agent.</li></ul><div class="agent-foot" id="agentFoot">Analysis workspace only. No MT5 order is sent.</div>`;
const disclaimer=document.getElementById('disclaimer');if(disclaimer&&disclaimer.parentNode===root)root.insertBefore(panel,disclaimer);else root.append(panel);

const chart=document.createElement('section');chart.id='atlas-chart-panel';chart.className='card atlas-chart-panel';
chart.innerHTML=`<div class="chart-head"><div><div class="label">AI Chart</div><div class="mini">Editable market chart with ATLAS setup context and indicator overlays.</div></div><div class="chart-controls"><select id="chartSymbol"><option>XAUUSD</option><option>GAS</option><option>XAGUSD</option><option>EURUSD</option><option>XRPUSDT</option><option>SOLUSDT</option></select><select id="chartInterval"><option>5m</option><option selected>15m</option><option>30m</option><option>1h</option><option>4h</option><option>1d</option></select><select id="chartIndicator"><option value="price">Price</option><option value="ema20">Price + EMA20</option><option value="rsi14">Price + RSI14</option></select><button id="chartRefresh">Refresh</button></div></div><div class="atlas-chart-wrap"><svg id="atlasChart" class="atlas-chart" viewBox="0 0 1000 320" preserveAspectRatio="none" role="img" aria-label="ATLAS market chart"></svg></div><div class="chart-meta" id="chartMeta">Loading chart…</div>`;
panel.insertAdjacentElement('afterend',chart);

const chat=document.createElement('section');chat.id='atlas-chat-panel';chat.className='card atlas-chat-panel';
chat.innerHTML=`<div class="chat-head"><div><div class="label">ATLAS AI Chat</div><div class="mini">Ask about markets, setups, risk, and ATLAS features.</div></div><span class="chart-signal">INFORMATIONAL AI</span></div><div class="chat-log" id="atlasChatLog" aria-live="polite"></div><div class="chat-compose"><input id="atlasChatInput" class="atlas-chat-input" maxlength="4000" placeholder="Ask ATLAS about XAUUSD, risk, setups, or platform features…"><div class="chat-actions"><button id="atlasChatSend">Ask ATLAS</button></div></div><div class="chat-foot">No order is sent from chat. Answers are analysis and product guidance, not a guarantee of trading outcomes.</div>`;
chart.insertAdjacentElement('afterend',chat);

const esc=v=>String(v==null?'':v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const decision=document.getElementById('agentDecision'),confidence=document.getElementById('agentConfidence'),trend=document.getElementById('agentTrend'),risk=document.getElementById('agentRisk'),skills=document.getElementById('agentSkills'),reasons=document.getElementById('agentReasons'),foot=document.getElementById('agentFoot'),run=document.getElementById('agentRun'),frames=document.getElementById('agentFrames');
function toneDecision(v){decision.className='agent-value '+(v==='PAPER_CANDIDATE'||v==='BUY'||v==='SELL'?'green':v==='WAIT'||v==='NO_TRADE'?'yellow':'red')}
async function analyze(){run.disabled=true;run.textContent='Analyzing…';decision.textContent='…';confidence.textContent='—';trend.textContent='—';risk.textContent='—';frames.innerHTML='';skills.innerHTML='';reasons.innerHTML='';try{const selected=document.getElementById('agentInterval').value;const payload={symbol:document.getElementById('agentSymbol').value,interval:selected==='multi'?'1h':selected,multi_timeframe:selected==='multi',limit:120,account_balance:10000,risk_percent:1};const response=await fetch('/agent/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(data.detail||'Agent unavailable');decision.textContent=data.decision||data.status||'WAIT';toneDecision(decision.textContent);confidence.textContent=Number(data.confidence||0).toFixed(1)+'%';trend.textContent=String((data.technical||{}).trend||'unknown').toUpperCase();frames.innerHTML=Object.entries(data.timeframe_decisions||{}).map(([tf,f])=>'<div class="agent-metric"><div class="label">'+esc(tf)+'</div><div class="agent-value">'+esc(f.decision)+'</div><div>'+esc((f.signal||{}).direction||f.status)+' · '+esc(f.confidence)+'%</div><div>Risk: '+((f.risk||{}).approved===true?'PASSED':'BLOCKED')+'</div><ul class="agent-reasons">'+(f.rationale||[]).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>').join('');const r=data.risk||{};risk.textContent=r.approved===true?'PASSED':r.approved===false?'REJECTED':'N/A';risk.className='agent-value '+(r.approved===true?'green':r.approved===false?'red':'yellow');skills.innerHTML=(data.selected_skills||[]).map(x=>'<span class="tag">'+esc(x)+'</span>').join('');reasons.innerHTML=(data.rationale||[]).map(x=>'<li>'+esc(x)+'</li>').join('')||'<li>No additional rationale.</li>';foot.textContent='Mode: analysis · '+esc(data.symbol)+' · '+esc(data.interval)+' · No MT5 order sent.'}catch(error){decision.textContent='UNAVAILABLE';decision.className='agent-value red';confidence.textContent='—';trend.textContent='—';risk.textContent='—';skills.innerHTML='';frames.innerHTML='';reasons.innerHTML='<li>'+esc(error.message||'Agent unavailable')+'</li>';foot.textContent='ATLAS Agent analysis could not be loaded.'}finally{run.disabled=false;run.textContent='Analyze'}}
run.addEventListener('click',analyze);

document.getElementById('agentSymbol').addEventListener('change',e=>{document.getElementById('chartSymbol').value=e.target.value;refreshChart()});
function ema(values,period){const k=2/(period+1);let last=values[0]||0;return values.map((v,i)=>{last=i===0?v:(v*k+last*(1-k));return last})}
function rsi(values,period=14){const out=new Array(values.length).fill(50);let gains=0,losses=0;for(let i=1;i<values.length;i++){const d=values[i]-values[i-1];if(i<=period){gains+=Math.max(0,d);losses+=Math.max(0,-d);if(i===period){let ag=gains/period,al=losses/period;out[i]=al===0?100:100-(100/(1+ag/al));for(let j=i+1;j<values.length;j++){const dd=values[j]-values[j-1];ag=(ag*(period-1)+Math.max(0,dd))/period;al=(al*(period-1)+Math.max(0,-dd))/period;out[j]=al===0?100:100-(100/(1+ag/al))}break}}}return out}
function linePath(values,min,max,h=280,top=20){const span=Math.max(max-min,1e-9);return values.map((v,i)=>{const x=20+(i/Math.max(values.length-1,1))*960;const y=top+(1-(v-min)/span)*h;return (i?'L':'M')+x.toFixed(1)+' '+y.toFixed(1)}).join(' ')}
async function refreshChart(){const button=document.getElementById('chartRefresh'),svg=document.getElementById('atlasChart'),meta=document.getElementById('chartMeta');button.disabled=true;meta.textContent='Refreshing chart…';try{const symbol=document.getElementById('chartSymbol').value,interval=document.getElementById('chartInterval').value,indicator=document.getElementById('chartIndicator').value;const [response,setupsResponse]=await Promise.all([fetch('/dashboard/chart-data?symbol='+encodeURIComponent(symbol)+'&interval='+encodeURIComponent(interval)+'&limit=120',{cache:'no-store'}),fetch('/dashboard/active-setups',{cache:'no-store'}).catch(()=>null)]);const data=await response.json();if(!response.ok)throw Error(data.detail||'Chart unavailable');const candles=Array.isArray(data.candles)?data.candles:[];const closes=candles.map(x=>Number(x.close)).filter(Number.isFinite);if(closes.length<2)throw Error('Not enough chart data');const low=Math.min(...closes),high=Math.max(...closes);let markup='<line class="chart-grid" x1="20" y1="80" x2="980" y2="80"/><line class="chart-grid" x1="20" y1="160" x2="980" y2="160"/><line class="chart-grid" x1="20" y1="240" x2="980" y2="240"/><path class="chart-price" d="'+linePath(closes,low,high)+'"/>';let indicatorLabel='Price';if(indicator==='ema20'){markup+='<path class="chart-ema" d="'+linePath(ema(closes,20),low,high)+'"/>';indicatorLabel='EMA20'}else if(indicator==='rsi14'){markup+='<path class="chart-rsi" d="'+linePath(rsi(closes),0,100,70,225)+'"/>';indicatorLabel='RSI14'}markup+='<circle class="chart-marker" cx="980" cy="'+(20+(1-(closes.at(-1)-low)/Math.max(high-low,1e-9))*280).toFixed(1)+'" r="5"/>';svg.innerHTML=markup;let setupText='No qualified setup currently';if(setupsResponse&&setupsResponse.ok){const setups=await setupsResponse.json();const items=[...(setups.setups||[]),...(setups.watchlist||[])];const match=items.find(x=>x.symbol===symbol);if(match)setupText=(match.status||'WATCH')+' · '+(match.direction||'WAIT')+' · confidence '+Number(match.confidence||0).toFixed(1)+'%'}meta.textContent=symbol+' · '+interval+' · '+indicatorLabel+' · Last '+closes.at(-1).toFixed(4)+' · '+setupText}catch(error){svg.innerHTML='';meta.textContent=error.message||'Chart unavailable'}finally{button.disabled=false}}
document.getElementById('chartRefresh').addEventListener('click',refreshChart);document.getElementById('chartSymbol').addEventListener('change',refreshChart);document.getElementById('chartInterval').addEventListener('change',refreshChart);document.getElementById('chartIndicator').addEventListener('change',refreshChart);

const chatLog=document.getElementById('atlasChatLog'),chatInput=document.getElementById('atlasChatInput'),chatSend=document.getElementById('atlasChatSend');
function addChat(kind,text){const bubble=document.createElement('div');bubble.className='chat-bubble '+kind;bubble.textContent=text;chatLog.appendChild(bubble);chatLog.scrollTop=chatLog.scrollHeight}
async function askAtlas(){const request=chatInput.value.trim();if(!request)return;addChat('user',request);chatInput.value='';chatSend.disabled=true;chatSend.textContent='Thinking…';try{const response=await fetch('/agent/right-hand/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({request,interval:document.getElementById('chartInterval').value,multi_timeframe:true,account_balance:10000,risk_percent:1}),cache:'no-store'});const data=await response.json();if(!response.ok)throw Error(data.detail||'ATLAS AI unavailable');let text=data.message||'ATLAS completed the request.';const result=data.result||{};if(result.decision)text+='\nDecision: '+result.decision;if(result.confidence!=null)text+=' · Confidence: '+Number(result.confidence).toFixed(1)+'%';addChat('ai',text)}catch(error){addChat('ai',error.message||'ATLAS AI is unavailable right now.')}finally{chatSend.disabled=false;chatSend.textContent='Ask ATLAS'}}
chatSend.addEventListener('click',askAtlas);chatInput.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();askAtlas()}});
addChat('ai','ATLAS AI is ready. Ask about a supported market, current setup context, risk controls, or platform features.');
analyze();refreshChart();
})();
"""
